search_vector_example:
DEFINE INDEX article_vec ON TABLE article COLUMNS embedding HNSW;
CREATE article:1 CONTENT {title: "RAG with AxonBase", embedding: [0.12, 0.45, 0.78, 0.33]};
LET $query = [0.11, 0.44, 0.76, 0.35];
SELECT title, vector::distance::cosine(embedding, $query) AS dist FROM article WHERE embedding @@ $query ORDER BY vector::distance::cosine(embedding, $query) ASC LIMIT 5;

