-- Setup
DEFINE TABLE person SCHEMAFULL;
DEFINE FIELD name ON TABLE person TYPE string;

CREATE person:1 CONTENT {name: "Alice"};
CREATE person:2 CONTENT {name: "Bob"};
CREATE person:3 CONTENT {name: "Charlie"};
CREATE person:4 CONTENT {name: "Diana"};

RELATE person:1->knows->person:2;
RELATE person:2->knows->person:3;
RELATE person:3->knows->person:4;

-- Alice knows Diana? (3 hops)
RETURN graph::connected(person:1, person:4, "knows", 10);
-- Result: true

-- Path from Alice to Diana
RETURN graph::path(person:1, person:4, "knows", 10);
-- Result: ["person:1", "person:2", "person:3", "person:4"]

-- Limited depth (1 hop is not enough)
RETURN graph::connected(person:1, person:4, "knows", 1);
-- Result: false

