saga_correlation_code:
from urllib.request import Request, urlopen

def saga_update(bank):
    request = Request(
        "http://127.0.0.1:8000/sql",
        data=f'UPDATE \"{bank}\".\"account\":main SET balance = 75'.encode(),
        headers={
            "Content-Type": "text/plain",
            "Axon-Ns": "test",
            "Axon-Db": "orchestrator",
            "X-Correlation-Id": "four_bank_rollback_001",
        },
        method="POST",
    )
    with urlopen(request) as response:
        return response.read().decode()

for bank in ("bank1", "bank2", "bank3", "bank4"):
    saga_update(bank)

